mapper.select:
select x.*, sir.role_name from sys_internal_user x inner join sys_internal_role_user siru on x.id = siru.sys_user_id left join sys_internal_role sir on siru.role_id = sir.id where 1 = 1 and x.del_flag = '0' and siru.del_flag = '0' and sir.del_flag = '0'
and siru.role_id = #{condition.roleId}
and x.user_code = #{condition.userCode}
and x.user_name like concat('%',#{condition.userName}::text,'%')

select distinct u.user_code, u.user_name from sys_internal_sub_user sisu inner join sys_internal_user x on sisu.parent_user_id = x.id inner join sys_internal_role_user siru on x.id = siru.sys_user_id inner join sys_internal_role sir on siru.role_id = sir.id left join sys_internal_user u on sisu.sub_user_id = u.id where 1 = 1 and sisu.del_flag = '0' and x.del_flag = '0' and siru.del_flag = '0' and siru.status = '0' and sir.del_flag = '0' and sir.status = '0'
and sir.role_code = #{condition.roleCode}
and x.user_code = #{condition.userCode}
